package com.genealogy.review.repository;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.genealogy.common.persistence.*; import com.genealogy.review.entity.RevisionEntity; import com.genealogy.review.repository.mybatis.RevisionPersistenceMapper; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Repository @Transactional(readOnly=true) public class RevisionRepository { private final RevisionPersistenceMapper mapper; public RevisionRepository(RevisionPersistenceMapper mapper){this.mapper=mapper;} @Transactional public RevisionEntity save(RevisionEntity e){e.ensureTraceId();if(e.getId()==null)mapper.insertRecord(e);else if(mapper.updateAllById(e)!=1)throw new IllegalStateException("Revision update expected one row for id "+e.getId());return e;} @Transactional public RevisionEntity saveAndFlush(RevisionEntity e){return save(e);} public Optional<RevisionEntity> findById(Long id){return Optional.ofNullable(id==null?null:mapper.selectById(id));} public List<RevisionEntity> findAllById(Iterable<Long> ids){List<Long>v=new ArrayList<>();if(ids!=null)ids.forEach(v::add);return v.isEmpty()?List.of():mapper.selectBatchIds(v);} public Optional<RevisionEntity> findByIdAndTargetType(Long id,String type){return Optional.ofNullable(mapper.selectOne(Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getId,id).eq(RevisionEntity::getTargetType,type)));} public Optional<RevisionEntity> findByTraceId(UUID traceId){return Optional.ofNullable(mapper.selectOne(Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getTraceId,traceId).orderByDesc(RevisionEntity::getId).last("limit 1")));} public Optional<RevisionEntity> findFirstByClanIdAndTargetTypeAndTargetIdOrderBySubmitTimeDesc(Long clanId,String type,Long targetId){return Optional.ofNullable(mapper.selectOne(Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getClanId,clanId).eq(RevisionEntity::getTargetType,type).eq(RevisionEntity::getTargetId,targetId).orderByDesc(RevisionEntity::getSubmitTime).orderByDesc(RevisionEntity::getId).last("limit 1")));} public boolean existsByTargetTypeAndTargetIdAndStatus(String type,Long id,String status){return mapper.selectCount(Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getTargetType,type).eq(RevisionEntity::getTargetId,id).eq(RevisionEntity::getStatus,status))>0;} public List<RevisionEntity> findByTargetTypeAndTargetIdInAndStatusAndChangeTypeIn(String type,Collection<Long> ids,String status,Collection<String> changes){if(ids==null||ids.isEmpty()||changes==null||changes.isEmpty())return List.of();return mapper.selectList(Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getTargetType,type).in(RevisionEntity::getTargetId,ids).eq(RevisionEntity::getStatus,status).in(RevisionEntity::getChangeType,changes).orderByAsc(RevisionEntity::getTargetId).orderByAsc(RevisionEntity::getId));} public List<TargetCountProjection> countByTargets(Long clanId,String type,Collection<Long> ids){if(ids==null||ids.isEmpty())return List.of();return new ArrayList<>(mapper.countByTargets(clanId,type,ids));} public List<RevisionEntity> findTreeRevisionsByTargets(Long clanId,Collection<String> types,Collection<Long> ids){if(types==null||types.isEmpty()||ids==null||ids.isEmpty())return List.of();return mapper.findTreeRevisionsByTargets(clanId,types,ids);} public Page<RevisionEntity> findByClanIdAndTargetTypeAndTargetIdOrderBySubmitTimeDesc(Long clanId,String type,Long targetId,Pageable p){var q=Wrappers.<RevisionEntity>lambdaQuery().eq(RevisionEntity::getClanId,clanId).eq(RevisionEntity::getTargetType,type).eq(RevisionEntity::getTargetId,targetId);long total=mapper.selectCount(q);if(total==0)return new PageImpl<>(List.of(),p,0);q.orderByDesc(RevisionEntity::getSubmitTime).orderByDesc(RevisionEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset());return new PageImpl<>(mapper.selectList(q),p,total);} }
